'use client';

import React, { useEffect, useMemo, useState } from 'react';
import {
    Cloud,
    fetchSimpleIcons,
    renderSimpleIcon,
} from 'react-icon-cloud';

const iconSlugs = [
    // Mobile
    'flutter',
    'dart',
    'android',
    'apple',

    // Backend / Database
    'firebase',
    'mysql',
    'mongodb',
    'sqlite',
    'postgresql',
    'postman',
    'nodejs',
    'express',
    'prisma',
    'redis',

    // Frontend
    'react',
    'nextdotjs',
    'typescript',
    'javascript',
    'html5',
    'css3',
    'tailwindcss',
    'vuejs',
    'angular',

    // Tools
    'git',
    'github',
    'gitlab',
    'docker',
    'python',
    'wordpress',
    'stripe',
    'googlemaps',
    'figma',
    'jira',
    'vercel',
    'amazonaws',
    'kubernetes',
];

const ICON_COLOR = '#AEB6C2';

export default function IconGlobe() {
    const [data, setData] = useState(null);
    const [isHovered, setIsHovered] = useState(false);

    useEffect(() => {
        let mounted = true;

        async function loadIcons() {
            try {
                const result = await fetchSimpleIcons({
                    slugs: iconSlugs,
                });

                if (mounted) {
                    setData(result);
                }
            } catch (error) {
                console.error('Error loading icons:', error);
            }
        }

        loadIcons();

        return () => {
            mounted = false;
        };
    }, []);

    const renderedIcons = useMemo(() => {
        if (!data?.simpleIcons) {
            return null;
        }

        const icons = Object.values(data.simpleIcons).filter(Boolean);

        return icons
            .map((icon, index) => {
                try {
                    const sizes = [34, 38, 42, 46, 50, 56];

                    const opacityValues = [
                        0.35,
                        0.42,
                        0.50,
                        0.58,
                        0.46,
                        0.38,
                    ];

                    const size = sizes[index % sizes.length];

                    const opacity =
                        opacityValues[index % opacityValues.length];

                    return renderSimpleIcon({
                        icon,
                        size,
                        bgHex: 'transparent',
                        fallbackHex: ICON_COLOR,
                        minContrastRatio: 0,

                        aProps: {
                            href: undefined,
                            tabIndex: -1,

                            onClick: (event) => {
                                event.preventDefault();
                            },

                            onFocus: (event) => {
                                event.target.blur();
                            },

                            style: {
                                pointerEvents: 'none',
                                outline: 'none',
                                border: 'none',
                                WebkitTapHighlightColor: 'transparent',
                                filter: 'grayscale(100%)',
                                opacity,
                            },
                        },
                    });
                } catch (error) {
                    console.warn(
                        'Could not render icon:',
                        icon,
                        error
                    );

                    return null;
                }
            })
            .filter(Boolean);
    }, [data]);

    return (
        <div
            className="icon-globe-wrapper relative flex items-center justify-center w-full max-w-[650px] h-[600px] mx-auto overflow-hidden"
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
        >
            <style jsx global>{`
                .icon-globe-wrapper {
                    background: transparent;
                }

                .icon-globe-wrapper canvas {
                    outline: none !important;
                    border: none !important;
                }

                .icon-globe-wrapper a,
                .icon-globe-wrapper a:hover,
                .icon-globe-wrapper a:focus,
                .icon-globe-wrapper a:active,
                .icon-globe-wrapper a:focus-visible {
                    outline: none !important;
                    border: none !important;
                    box-shadow: none !important;
                    -webkit-tap-highlight-color: transparent !important;
                }
            `}</style>

            <Cloud
                options={{
                    initial: [0.08, -0.08],

                    maxSpeed: isHovered ? 0.003 : 0.006,

                    minSpeed: isHovered ? 0.001 : 0.003,

                    decel: 0.96,

                    activeCursor: 'default',

                    tooltip: null,

                    outlineColour: '#0000',

                    outlineOffset: 0,

                    clickToFront: false,

                    dragControl: true,

                    dragVelocity: 0.35,

                    wheelZoom: false,

                    depth: 1.15,

                    imageScale: 2.2,

                    reverse: true,
                }}
            >
                {renderedIcons}
            </Cloud>
        </div>
    );
}